/**
 * The Page envelope every paginated route answers with.
 *
 * A Page serializes as `{ items, total, offset, limit, maxLimit }`. `offset` and
 * `limit` are the APPLIED window, so a client that sent no size learns the size
 * the server used and can number pages; `maxLimit` is `PAGE_MAX_LIMIT`, the
 * largest size this deployment profile accepts. `total` counts the same chain
 * the items are cut from, with only the window removed.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 */
export interface Page<T> {
  items: T[];
  total: number;
  offset: number;
  limit: number;
  maxLimit: number;
}

/**
 * The largest page size this deployment profile accepts (`maxPageSize`, at most
 * `MAX_PAGE_SIZE`): the bound every paginated route enforces and every page reports.
 */
export const PAGE_MAX_LIMIT = 100;

/** What a page query reads of a request: the row window to cut. */
export interface PageWindow {
  readonly offset: number;
  readonly limit: number;
}

/** Build the envelope from one window's rows, the chain's total and the window. */
export function toPage<T>(items: T[], total: number, window: PageWindow): Page<T> {
  return {
    items: items,
    total: total,
    offset: window.offset,
    limit: window.limit,
    maxLimit: PAGE_MAX_LIMIT,
  };
}

/** The order a sortable list accepts in `sortOrder`. */
export type SortOrder = 'asc' | 'desc';

/** One order key, `{ property: direction }`, as a MikroORM order map takes it. */
export type OrderKey = Record<string, SortOrder>;

/**
 * The requested field as the leading order key, or none when the request named none.
 *
 * `sortBy` is looked up in the route's allow-map from wire value to property; the route's
 * pipe refused any other value as a request-validation problem before the query was
 * built, so no ordering is ever built from request text.
 */
export function requestedOrder(
  sortBy: string | undefined,
  sortOrder: SortOrder | undefined,
  columns: Readonly<Record<string, string>>,
): OrderKey[] {
  if (sortBy === undefined) {
    return [];
  }
  const property = columns[sortBy];
  if (property === undefined) {
    throw new Error(`sortBy '${sortBy}' is not one of the route's sort fields`);
  }
  return [{ [property]: sortOrder ?? 'asc' }];
}

/** The part of a MikroORM QueryBuilder a page query uses. */
export interface PageableQuery<T> {
  offset(offset: number): PageableQuery<T>;
  limit(limit: number): PageableQuery<T>;
  getResultAndCount(): Promise<[T[], number]>;
}

/**
 * Run a query chain for one window and count the same chain.
 *
 * The items are the chain with the window applied after its own ordering. The total is
 * `getResultAndCount`'s count over a clone of the builder with its ordering, limit and
 * offset cleared, so it carries every predicate of the items (tenant scope included) and
 * can never see a row the items could not. Both run on the builder's one entity manager.
 */
export async function pageOf<T>(query: PageableQuery<T>, window: PageWindow): Promise<Page<T>> {
  const [items, total] = await query
    .offset(window.offset)
    .limit(window.limit)
    .getResultAndCount();
  return toPage(items, total, window);
}

/**
 * One window of an array a route already computed, with the array's length as the total.
 *
 * The elements are those from `window.offset` for `window.limit` (none once the offset passes
 * the end); `total` counts every element, so a client numbers its pages exactly
 * as it does for a page cut from a query.
 */
export function pageOfItems<T>(items: T[], window: PageWindow): Page<T> {
  return toPage(items.slice(window.offset, window.offset + window.limit), items.length, window);
}

/**
 * The same window and total over one mapped value per row: a page of a struct.
 *
 * A route answering `Page<S>` for a struct `S` reads its rows as a page of the entity, then
 * builds one `S` per row of that window; the rows were already ordered and cut by the query,
 * so the total, offset and limit stay the page's.
 */
export async function mapPage<T, S>(
  page: Page<T>,
  map: (row: T) => S | Promise<S>,
): Promise<Page<S>> {
  return { ...page, items: await Promise.all(page.items.map(map)) };
}
